void adjust_bpf_jumps(struct bpf_prog *prog, int pos, int delta) {
    for (int i = 0; i < prog->len; i++) {
        struct bpf_insn *insn = &prog->insnsi[i];
        if ((insn->code & BPF_CLASS) == BPF_JMP &&
            (insn->code & BPF_OP) != BPF_JA &&
            (insn->code & BPF_OP) != BPF_EXIT) {
            int offset = insn->off;
            if (i >= pos) {
                insn->off = offset + delta;
            }
        }
    }
}

void adjust_bpf_jumps(struct bpf_prog *prog, int pos, int delta) {
    for (int i = 0; i < prog->len; i++) {
        struct bpf_insn *insn = &prog->insnsi[i];

        // Check if the instruction is a jump (JMP) type
        if (BPF_CLASS(insn->code) == BPF_JMP) {
            // Skip call and exit pseudo instructions
            if (insn->jt != 0 || insn->jf != 0) {
                // Adjust the offset if the instruction is after or before the 'pos' position
                if (i >= pos) {
                    insn->off -= delta;
                } else {
                    insn->off += delta;
                }
            }
        }
    }
}

void adjust_bpf_jumps(struct bpf_prog *prog, int pos, int delta) {
    for (int i = 0; i < prog->len; i++) {
        struct bpf_insn *insn = &prog->insnsi[i];
        if (insn->code == (BPF_JMP | BPF_JA)) {
            /* Jump absolute */
            if (insn->off != 0) {
                if (i < pos) {
                    insn->off += delta;
                } else if (i >= pos) {
                    insn->off -= delta;
                }
            }
        } else if (BPF_CLASS(insn->code) == BPF_JMP) {
            /* Jump conditional */
            if (insn->off != 0) {
                if (i < pos) {
                    insn->off += delta;
                } else if (i >= pos) {
                    insn->off -= delta;
                }
            }
        }
    }
}

void adjust_bpf_jumps(struct bpf_prog *prog, int pos, int delta) {
    for (int i = 0; i < prog->len; i++) {
        struct bpf_insn *insn = &prog->insnsi[i];
        if ((insn->code & BPF_CLASS_MASK) == BPF_JMP) {
            if ((insn->code & BPF_OP_MASK) != BPF_JA && (insn->code & BPF_OP_MASK) != BPF_JMP32 && (insn->code & BPF_OP_MASK) != BPF_JMP) {
                int target = insn->off;
                if (target >= pos) {
                    insn->off += delta;
                }
            }
        }
    }
}

